class MetasploitModule < Msf::Auxiliary
  LOGIN_PATH = '/api/v1/login'.freeze

  include Msf::Exploit::Remote::HttpClient
  include Msf::Auxiliary::Scanner
  include Msf::Auxiliary::Report

  def initialize(info = {})
    super(
      update_info(
        info,
        'Name' => 'Rocket.Chat 9.1 Livechat transcript HTML relay scanner (VULN-051)',
        'Description' => %q{
          Rocket.Chat is a self-hosted team chat server. Its Omnichannel transcript
          route is anonymous by design, authorised by the visitor token the widget
          holds, and it mails a whole conversation to an address the caller names,
          from the workspace's own address. Message text is escaped in that mail, but
          an upload's description is not, so markup that a visitor put in the
          conversation arrives live in mail from the organisation itself. This scanner
          changes nothing: it confirms Omnichannel is enabled from the anonymous
          public-settings document and reads the mailbox the operator names, reporting
          the host vulnerable when a transcript the workspace sent carries the markup
          unescaped.
        },
        'Author' => ['Blue Spider'],
        'License' => MSF_LICENSE,
        'References' => [
          ['URL', 'https://github.com/RocketChat/Rocket.Chat/issues'],
          ['URL', 'https://kohirc.com']
        ],
        'DisclosureDate' => '2026-11-24',
        'Notes' => {
          'Stability' => [CRASH_SAFE],
          'Reliability' => [],
          'SideEffects' => [IOC_IN_LOGS]
        }
      )
    )

    register_options([
      Opt::RPORT(39649),
      OptString.new('TARGETURI', [true, 'Base path to Rocket.Chat', '/api/v1/livechat/transcript']),
      OptString.new('MAILHOST', [true, 'Host of the operator\'s mailbox API (Mailpit or MailHog shape)', 'mailpit']),
      OptString.new('MAILPORT', [true, 'Port of that mailbox API', '8025']),
      OptString.new('MARKUP', [true, 'Markup to look for in a transcript the workspace mailed', '<h2>probe b1</h2>'])
    ])
  end

  def run_host(ip)
    res = public_settings_doc
    unless res
      vprint_error("#{peer} - No response")
      return
    end

    hit = public_setting('Livechat_enabled') == true && workspace_mail_carrying(datastore['MARKUP']) && !@mail_escaped
    unless hit
      vprint_status("#{peer} - Not vulnerable to VULN-051")
      return
    end

    print_good("#{peer} - Vulnerable: VULN-051")
    report_vuln(
      host: ip,
      port: rport,
      proto: 'tcp',
      sname: (ssl ? 'https' : 'http'),
      name: name,
      info: 'VULN-051 confirmed by Blue Spider',
      refs: references
    )
  end
  # The REST API answers 200 with {"success": false} for a refusal, so the
  # body, not the status line, is what a check has to read.
  def parse_json(res)
    return {} unless res

    doc = res.get_json_document
    doc.is_a?(Hash) ? doc : {}
  rescue StandardError
    {}
  end

  def api_error(res)
    doc = parse_json(res)
    doc['errorType'] || doc['error'] || doc['message'] || ''
  end

  # The workspace's own outbound mail is where this finding lands, so the
  # module reads the mailbox the operator names. That is a different host from
  # RHOST, so it goes through a client of its own rather than the HttpClient
  # mixin. Nothing is sent or deleted: the mailbox is only read.
  def mail_get(path)
    cli = Rex::Proto::Http::Client.new(datastore['MAILHOST'], datastore['MAILPORT'].to_i)
    cli.connect(10)
    res = cli.send_recv(cli.request_cgi('method' => 'GET', 'uri' => path), 20)
    cli.close
    res
  rescue StandardError => e
    vprint_error("#{peer} - could not read the mailbox at " \
                 "#{datastore['MAILHOST']}:#{datastore['MAILPORT']}: #{e}")
    nil
  end

  def mail_list(limit = 50)
    res = mail_get("/api/v1/messages?limit=#{limit}")
    return [] unless res

    doc = JSON.parse(res.body.to_s)
    doc['messages'] || doc['items'] || []
  rescue StandardError
    []
  end

  def mail_body(id)
    res = mail_get("/api/v1/message/#{id}")
    return '' unless res

    doc = JSON.parse(res.body.to_s)
    [doc['Subject'], doc['HTML'], doc['Text']].compact.join("\n")
  rescue StandardError
    res ? res.body.to_s : ''
  end

  # The mail that proves it: sent by the workspace itself, carrying text the
  # attacker chose, and carrying it live rather than escaped.
  def workspace_mail_carrying(marker, recipient = '', tries = 6)
    tries.times do |n|
      mail_list.each do |m|
        next unless recipient.empty? || m.to_s.include?(recipient)

        body = mail_body(m['ID'] || m['Id'] || m['id'])
        next unless body.include?(marker)

        @mail_subject = m['Subject'].to_s
        @mail_from = (m.dig('From', 'Address') || m['From']).to_s
        @mail_escaped = body.include?(escaped(marker))
        vprint_status("#{peer} - mail #{(m['ID'] || '').to_s[0, 12]} from " \
                      "#{@mail_from}: #{@mail_subject[0, 70].inspect}")
        return true
      end
      sleep(2) unless n == tries - 1
    end
    false
  end

  def escaped(marker)
    marker.gsub('&', '&amp;').gsub('<', '&lt;').gsub('>', '&gt;')
  end

  # The anonymous public-settings document says whether the feature that owns
  # this sink is switched on at all: without it the code path is unreachable,
  # so a host that has it off is not vulnerable however old the build is.
  # This is also the module's own request to the target: it reads state and
  # changes nothing.
  def public_settings_doc
    send_request_cgi({
      'method' => 'GET',
      'uri' => normalize_uri('/api/v1/settings.public'),
      'vars_get' => { 'count' => '0' }
    })
  end

  def public_setting(id)
    res = @settings_doc ||= public_settings_doc
    return nil unless res

    (parse_json(res)['settings'] || []).each do |s|
      return s['value'] if s['_id'] == id
    end
    nil
  rescue StandardError
    nil
  end
end
